#' Validate a Published Model
#'
#' Validate a published prediction model, or one exported by clinpred, in the 
#' current data: the model is read from a JSON file exported by clinpred or 
#' from a table of coefficients (term, estimate, SE), applied unchanged, and 
#' its discrimination, calibration, overall performance and clinical utility 
#' are measured; the model can be updated (recalibrated or revised) by the 
#' closed testing procedure.
#'
#' @examples
#' \donttest{
#' # coefs.csv: term,estimate / Intercept,-9.1 / glu,0.037 / bmi,0.08
#' cpPublished(data = MASS::Pima.te, modelFile = list(path = "coefs.csv",
#'             filename = "coefs.csv"), family = "binary", dep = "type",
#'             eventLevel = "Yes")
#'}
#' @param data the data as a data frame
#' @param modelFile a model exported by clinpred (json), or a table of
#'   coefficients (csv, tsv, txt or xlsx) with the columns term, estimate and,
#'   optionally, SE
#' @param family \code{'binary'}, \code{'gaussian'} or \code{'cox'}
#' @param dep the outcome (binary or continuous), or for a Cox model the event
#'   indicator
#' @param eventLevel the level of the outcome that is the event; '' uses the
#'   second level
#' @param time the follow-up time (Cox models)
#' @param covs the variables the model uses (jamovi passes an analysis only
#'   the variables in its boxes); terms are matched to them by name
#' @param horizon Cox models: the time by which risks are assessed; 0
#'   (default) uses the model file's horizon, else the median follow-up
#' @param ciWidth .
#' @param updating .
#' @param updAlpha .
#' @param classif .
#' @param thrMethod .
#' @param threshold .
#' @param dca .
#' @param dcaMax .
#' @param nbThresholds .
#' @param calPlot .
#' @param calGroups .
#' @param rocPlot .
#' @param kmPlot .
#' @param kmGroups .
#' @param explain .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$instructions} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$modelTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$check} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$samples} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$perf} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$updTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$confTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$classTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$nbTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$plots$calibration} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plots$roc} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plots$kmCurves} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plots$dcaCurves} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$pred} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$predLP} \tab \tab \tab \tab \tab an output \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$modelTable$asDF}
#'
#' \code{as.data.frame(results$modelTable)}
#'
#' @export
cpPublished <- function(
    data,
    modelFile = NULL,
    family = "binary",
    dep = NULL,
    eventLevel = "",
    time = NULL,
    covs = list(),
    horizon = 0,
    ciWidth = 95,
    updating = FALSE,
    updAlpha = 0.05,
    classif = FALSE,
    thrMethod = "value",
    threshold = 0.5,
    dca = FALSE,
    dcaMax = 0.5,
    nbThresholds = "0.05, 0.1, 0.2",
    calPlot = FALSE,
    calGroups = 10,
    rocPlot = FALSE,
    kmPlot = FALSE,
    kmGroups = 4,
    explain = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("cpPublished requires jmvcore to be installed (restart may be required)")

    if ( ! missing(dep)) dep <- jmvcore::resolveQuo(jmvcore::enquo(dep))
    if ( ! missing(time)) time <- jmvcore::resolveQuo(jmvcore::enquo(time))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(dep), dep, NULL),
            `if`( ! missing(time), time, NULL),
            `if`( ! missing(covs), covs, NULL))


    options <- cpPublishedOptions$new(
        modelFile = modelFile,
        family = family,
        dep = dep,
        eventLevel = eventLevel,
        time = time,
        covs = covs,
        horizon = horizon,
        ciWidth = ciWidth,
        updating = updating,
        updAlpha = updAlpha,
        classif = classif,
        thrMethod = thrMethod,
        threshold = threshold,
        dca = dca,
        dcaMax = dcaMax,
        nbThresholds = nbThresholds,
        calPlot = calPlot,
        calGroups = calGroups,
        rocPlot = rocPlot,
        kmPlot = kmPlot,
        kmGroups = kmGroups,
        explain = explain)

    analysis <- cpPublishedClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

